package io.github.jesterportfolio.hearth.survival;

import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import io.github.jesterportfolio.hearth.survival.platform.*;
import io.github.jesterportfolio.hearth.economy.*;

class PlatformTest {
    @TempDir Path root;
    static Properties defaults()throws Exception{var p=new Properties();try(var in=PlatformTest.class.getResourceAsStream("/platform.properties")){p.load(in);}return p;}
    @Test void operatingValuesAreDeferredAndActionsDefaultOff()throws Exception{var p=PlatformSettings.parse(defaults());assertFalse(p.upgrade());assertFalse(p.autosell());assertFalse(p.resourceReset());assertTrue(p.goods().isEmpty());}
    @Test void invalidBooleanFormulaAndBoundsAreRejected()throws Exception{var p=defaults();p.setProperty("upgrade.enabled","yes");assertThrows(IllegalArgumentException.class,()->PlatformSettings.parse(p));p.setProperty("upgrade.enabled","false");p.setProperty("upgrade.chance","level/2");assertThrows(IllegalArgumentException.class,()->PlatformSettings.parse(p));p.setProperty("upgrade.chance","1");p.setProperty("autosell.interval-ticks","0");assertThrows(IllegalArgumentException.class,()->PlatformSettings.parse(p));}
    @Test void perLevelCostAndMaterialsRemainConfiguration()throws Exception{var p=defaults();p.setProperty("upgrade.cost","100*level");p.setProperty("upgrade.chance","1/level");p.setProperty("upgrade.material.IRON_INGOT","2");var s=PlatformSettings.parse(p);assertEquals(300,s.cost().evaluate(Map.of("level",3.0)));assertEquals(2,s.materials().get("IRON_INGOT"));}
    @Test void repeatedSourcesDoNotMultiplyAndNamespacesRemainSeparate(){var ledger=new StatLedger();var id=UUID.randomUUID();var a=Map.of("weapon",new StatLedger.Contribution("auraskills/strength",3));ledger.replace(id,"equipment",a);ledger.replace(id,"equipment",a);assertEquals(3,ledger.view(id).totals().get("auraskills/strength"));ledger.replace(id,"enchants",a);assertEquals(6,ledger.view(id).totals().get("auraskills/strength"));ledger.replace(id,"equipment",Map.of());assertEquals(3,ledger.view(id).totals().get("auraskills/strength"));assertEquals(1,ledger.view(id).sources().size());}
    @Test void invalidContributionCannotPartiallyReplaceExistingSources(){var ledger=new StatLedger();var id=UUID.randomUUID();ledger.replace(id,"equipment",Map.of("a",new StatLedger.Contribution("hearth/power",3)));var invalid=new HashMap<String,StatLedger.Contribution>();invalid.put("b",null);assertThrows(NullPointerException.class,()->ledger.replace(id,"equipment",invalid));assertEquals(3,ledger.view(id).totals().get("hearth/power"));}
    @Test void maxStackingAndCapsAreDeterministic(){var ledger=new StatLedger();ledger.policy("MAX_ABSOLUTE",5);var id=UUID.randomUUID();ledger.replace(id,"one",Map.of("a",new StatLedger.Contribution("hearth/power",4)));ledger.replace(id,"two",Map.of("b",new StatLedger.Contribution("hearth/power",9)));assertEquals(5,ledger.view(id).totals().get("hearth/power"));ledger.replace(id,"two",Map.of());assertEquals(4,ledger.view(id).totals().get("hearth/power"));ledger.clear(id);assertTrue(ledger.view(id).totals().isEmpty());assertEquals(0,ledger.playerCount());}
    @Test void invalidStatSourcesCannotPublish(){var ledger=new StatLedger();assertThrows(IllegalArgumentException.class,()->new StatLedger.Contribution("Runtime.exec",1));assertThrows(IllegalArgumentException.class,()->new StatLedger.Contribution("hearth/power",Double.NaN));assertThrows(IllegalArgumentException.class,()->ledger.replace(UUID.randomUUID(),"../source",Map.of()));}
    ConfigurationChanges.Plan staged(ConfigurationChanges c)throws Exception{Files.writeString(root.resolve("platform.properties"),"version=1\nvalue=old\n");Files.writeString(root.resolve("new.candidate"),"version=1\nvalue=new\n");return c.stage("platform.properties","new.candidate",(n,a,b)->{});}
    @Test void configurationChangePreservesBeforeAfterAndSupportsRollback()throws Exception{var c=new ConfigurationChanges(root);var p=staged(c);c.publish(p,false,(n,a,b)->{});assertTrue(Files.readString(root.resolve("platform.properties")).contains("new"));assertEquals("APPLIED",c.state(p));assertEquals(1,c.pending().size());c.mark(p,"COMMITTED");assertTrue(c.pending().isEmpty());c.publish(p,true,(n,a,b)->{});assertTrue(Files.readString(root.resolve("platform.properties")).contains("old"));assertEquals("ROLLED_BACK",c.state(p));assertTrue(Files.exists(p.directory().resolve("after")));}
    @Test void changedOriginalNeverGetsOverwritten()throws Exception{var c=new ConfigurationChanges(root);var p=staged(c);Files.writeString(root.resolve("platform.properties"),"foreign change");assertThrows(Exception.class,()->c.publish(p,false,(n,a,b)->{}));assertEquals("foreign change",Files.readString(root.resolve("platform.properties")));}
    @Test void partialPublishCanBeInspectedAndResumedWithoutRegeneratingResult()throws Exception{var c=new ConfigurationChanges(root);var p=staged(c);c.publish(p,false,(n,a,b)->{});var next=new ConfigurationChanges(root);assertEquals(p.id(),next.pending().getFirst().id());next.publish(next.plan(p.id()),false,(n,a,b)->{fail("already published candidate must not be regenerated");});assertEquals(p.after(),ConfigurationChanges.hash(Files.readAllBytes(root.resolve("platform.properties"))));}
    @Test void tamperedEvidenceAndUnsafePathsAreRejected()throws Exception{var c=new ConfigurationChanges(root);var p=staged(c);Files.writeString(p.directory().resolve("after"),"tampered");assertThrows(Exception.class,()->c.plan(p.id()));assertThrows(Exception.class,()->c.stage("../secret","new.candidate",(n,a,b)->{}));}
    @Test void symlinkCandidateIsRejected()throws Exception{Files.writeString(root.resolve("platform.properties"),"old");Files.createSymbolicLink(root.resolve("linked.candidate"),root.resolve("platform.properties"));var c=new ConfigurationChanges(root);assertThrows(Exception.class,()->c.stage("platform.properties","linked.candidate",(n,a,b)->{}));}
    @Test void failedValidationDoesNotChangeOriginal()throws Exception{Files.writeString(root.resolve("platform.properties"),"old");Files.writeString(root.resolve("new.candidate"),"bad");var c=new ConfigurationChanges(root);assertThrows(Exception.class,()->c.stage("platform.properties","new.candidate",(n,a,b)->{throw new IllegalArgumentException("invalid");}));assertEquals("old",Files.readString(root.resolve("platform.properties")));}
    static Properties economy()throws Exception{var p=new Properties();try(var in=PlatformTest.class.getResourceAsStream("/economy-demo.properties")){p.load(in);}p.setProperty("fixture-balance","0");return p;}
    @Test void economicNumericalPolicyCanChangeWithoutChangingIds()throws Exception{var before=economy();var after=(Properties)before.clone();after.setProperty("good.iron_ore.base","120");after.setProperty("facility.mine_ore.capacity","20");assertNotEquals(EconomyContent.parse(before).fingerprint(),EconomyPolicyMigration.validate(before,after).fingerprint());}
    @Test void economicIdentityAndUnrelatedSettingsAreFenced()throws Exception{var before=economy();var after=(Properties)before.clone();after.setProperty("good.iron_ore.material","DIAMOND");assertThrows(IllegalArgumentException.class,()->EconomyPolicyMigration.validate(before,after));after.setProperty("good.iron_ore.material","IRON_ORE");after.setProperty("merchant-region","mine");assertThrows(IllegalArgumentException.class,()->EconomyPolicyMigration.validate(before,after));}
    @Test void emptyRegistryCanAddDeclarationsAndCannotRemoveExistingIds(){var old=new Properties();for(String key:List.of("custom-skills","custom-stats","gear-stats"))old.setProperty(key,"");old.setProperty("hud-mode","off");var next=(Properties)old.clone();next.setProperty("custom-stats","power");next.setProperty("stat.power.name","Power");next.setProperty("stat.power.trait","auraskills/attack_damage");next.setProperty("stat.power.coefficient","1");ContentValidation.validate(old,next,id->false,id->true,id->true);assertThrows(IllegalArgumentException.class,()->ContentValidation.validate(next,old,id->false,id->true,id->true));next.setProperty("stat.power.coefficient","NaN");assertThrows(IllegalArgumentException.class,()->ContentValidation.validate(old,next,id->false,id->true,id->true));}
    @Test void metricsRemainFiniteNamedAggregates(){var m=new PlatformMetrics();m.record("upgrade",10,false);m.record("upgrade",20,true);var s=m.snapshot().get("upgrade");assertEquals(2,s.count());assertEquals(1,s.failed());assertEquals(30,s.totalNanos());assertEquals(20,s.maximumNanos());assertThrows(IllegalArgumentException.class,()->m.record("user secret",1,false));}
}
